"""RB-Y1A+Sharpa mimic tasks."""

import gymnasium as gym

from ConTrack.tasks.manager_based.mimic_rby1a_sharpa import agents

gym.register(
    id="Isaac-Rby1a-Sharpa-Mimic-Manager-v0",
    entry_point="isaaclab.envs:ManagerBasedRLEnv",
    disable_env_checker=True,
    kwargs={
        "env_cfg_entry_point": f"{__name__}.rby1a_sharpa_env_cfg:Rby1aSharpaEnvCfg",
        "rsl_rl_cfg_entry_point": f"{agents.__name__}.rsl_rl_ppo_cfg:PPORunnerCfg",
    },
)

gym.register(
    id="Isaac-Rby1a-Sharpa-Mimic-Manager-Play-v0",
    entry_point="isaaclab.envs:ManagerBasedRLEnv",
    disable_env_checker=True,
    kwargs={
        "env_cfg_entry_point": f"{__name__}.rby1a_sharpa_env_cfg:Rby1aSharpaPlayEnvCfg",
        "rsl_rl_cfg_entry_point": f"{agents.__name__}.rsl_rl_ppo_cfg:PPORunnerCfg",
    },
)

